<?php $page_title='Wishlist';require 'includes/header.php';$total=(int)$pdo->query("SELECT COUNT(*) FROM wishlist")->fetchColumn();$top=$pdo->query("SELECT p.name,p.id,COUNT(w.id) wish_count FROM wishlist w JOIN products p ON p.id=w.product_id GROUP BY p.id,p.name ORDER BY wish_count DESC LIMIT 20")->fetchAll();?>
<div class="page-head"><div><h1>Wishlist</h1><p><?=$total?> total wishlist items across customers.</p></div></div><div class="panel"><h2>Most wishlisted products</h2><div class="table-wrap"><table><tr><th>Product</th><th>Product ID</th><th>Wishlist adds</th></tr><?php foreach($top as $x):?><tr><td><?=e($x['name'])?></td><td>#<?=$x['id']?></td><td><?=$x['wish_count']?></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>
